CREATE TABLE actual AS SELECT ((SELECT _rowid_ FROM t2 ORDER BY x DESC LIMIT 1 OFFSET 0)=(SELECT _rowid_ FROM t2 ORDER BY rowid LIMIT 1 OFFSET 2) AND (SELECT _rowid_ FROM t2 ORDER BY x DESC LIMIT 1 OFFSET 1)=(SELECT _rowid_ FROM t2 ORDER BY rowid LIMIT 1 OFFSET 1) AND (SELECT _rowid_ FROM t2 ORDER BY x DESC LIMIT 1 OFFSET 2)=(SELECT _rowid_ FROM t2 ORDER BY rowid LIMIT 1 OFFSET 0)) AS ok;